# Code generated by Claude
"""
The MPVI pipeline from text: an instruction goes through the Gemini planner and the Gemini labeling call, the plan runs in the simulator, from text to SUCCESS.

    MUJOCO_GL=egl python experiments/mpvi_text_test.py [--live] [--instruction "put the beaker on the hotplate"] [--no-stop-on-disagreement] [--out DIR]

Default (the suite): the stored replies of experiments/llm_cache are replayed, no API call (LLM mode cache_only; a missing reply is an error). With --live both calls go to the API (the cache is
bypassed for reading and the new replies are stored, so later runs replay them). stop_on_disagreement is ON (the labeling and the keyword cross-check must agree on every primitive) unless
--no-stop-on-disagreement is given. Every prompt and reply is written without the key to OUT/llm_log.json; OUT/summary.json has the plan, the tagged plan, the labels, the postprocess log (keyword
disagreements), the grounding log and the outcome.

Checks: the planner's plan fits the schema and has a navigation, a pick and a place segment in that order; no keyword disagreement; the episode outcome is SUCCESS with every segment done; the grounded
objects are the beaker and the hotplate; the log has the two calls with their prompts and replies and no key; the recording replays bit-identically.
"""

import argparse
import gc
import json
import os
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

from src.episode_runner import run_episode  # noqa: E402
from src.llm_gemini import GeminiCaller, LLMError  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.mpvi_planner import PlannerError, make_llm_planner  # noqa: E402
from src.mpvi_postprocess import PostprocessError, make_llm_labeler  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import LLM_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main(args):
    out = Path(args.out) if args.out else Path(tempfile.mkdtemp(prefix="mpvi_text_"))
    out.mkdir(parents=True, exist_ok=True)
    for sub in ("episode", "recording"):
        shutil.rmtree(out / sub, ignore_errors=True)
    caller = GeminiCaller(mode=args.mode or ("live" if args.live else "cache_only"))
    summary = {"instruction": args.instruction, "mode": caller.mode, "checker": args.checker, "model": LLM_CFG["model"], "stop_on_disagreement": not args.no_stop_on_disagreement}
    print(f"instruction: {args.instruction!r}   mode {caller.mode}   model {LLM_CFG['model']}   stop on disagreement {summary['stop_on_disagreement']}   checker {args.checker}")

    def finish(ok_text, error=None):
        caller.save_log(out / "llm_log.json")
        if error:
            summary["error"] = error
        (out / "summary.json").write_text(json.dumps(summary, indent=1, default=str))
        print(f"\nlog and summary in {out}")
    try:
        plan = make_llm_planner(caller.bind("plan", LLM_CFG["planner_prompt_version"]))(args.instruction)
        summary["plan"] = plan
        print("\nthe plan:\n" + "\n".join(f"  {i}. [{s['type']}] {s['description']}  (done when: {s['completion_criteria']}; target {s['target']})" for i, s in enumerate(plan["segments"])))
        sim = load_task(cameras=True)
        task = make_pipeline_task(plan, labeler=make_llm_labeler(caller.bind("label", LLM_CFG["label_prompt_version"])), stop_on_disagreement=not args.no_stop_on_disagreement,
                                  checker=args.checker, vlm_caller=caller)
    except (LLMError, PlannerError, PostprocessError) as e:
        print(f"\nSTOPPED before the episode: {type(e).__name__}: {e}")
        finish("stopped", f"{type(e).__name__}: {e}")
        check("the planner and the labeling call produced a usable, agreeing plan", False, f"{type(e).__name__}: {str(e)[:200]}")
        return
    tagged = task["tagged_plan"]
    summary["tagged_plan"] = tagged
    print("\nthe labels:\n" + "\n".join(f"  segment {s['index']}: {s['primitive']}  check={s['check']}  objects={[(o['phrase'], o['role']) for o in s['objects']]}  keywords say {s['keyword_primitive']}"
                                       for s in tagged["segments"] if s["type"] == "manipulation"))
    pl = tagged["postprocess"]["log"]
    print(f"keyword cross-check log: {pl if pl else 'no disagreement, nothing unmatched, nothing ambiguous'}")

    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", record_dir=out / "recording")
    pipe = task["pipeline"]
    state = pipe["orchestrator"]["state"]
    summary.update(outcome=s["outcome"], plan_failure=state["failure"], status=state["status"], grounded=state["grounded"], grounding_log=pipe["grounder"]["log"], verdicts=state["verdicts"],
                   monitors=state["monitors"], skill_end=state["skill_end"])
    print(f"\noutcome {s['outcome']}  plan failure: {state['failure']}")
    check("the plan has a pick and then a place, each after a navigation, and ends with the place",
          [x.get("primitive") for x in tagged["segments"] if x["type"] == "manipulation"] == ["pick", "place"] and tagged["segments"][0]["type"] == "navigation" and tagged["segments"][-1].get("primitive") == "place",
          f"{[(x['type'], x.get('primitive')) for x in tagged['segments']]}")
    check("no keyword disagreement, nothing unmatched or ambiguous", pl == [], f"{pl}")
    check("the episode outcome is SUCCESS and every segment is done", s["outcome"] == "SUCCESS" and all(x == "done" for x in state["status"]), f"{s['outcome']} {state['status']} {state['failure']}")
    ids = [{k: v for k, v in g.items() if k != "segment"} for g in state["grounded"]]
    check("the grounded objects are the beaker (pick) and the beaker and the hotplate (place)", ids == [{"manipulated": "beaker"}, {"manipulated": "beaker", "destination": "hotplate"}], f"{ids}")
    deciding = [v for v in state["verdicts"] if v["decides"]]
    print("\nthe checks (D = decides):")
    for v in state["verdicts"]:
        d = v.get("details") or {}
        if "vlm" in d:
            print(f"  segment {v['segment']} {v['event']} D  VLM {d['vlm']['verdict']} ({(d['vlm']['reply_text'] or d['vlm']['error'] or '').strip()[:60]!r})  oracle {'PASS' if d['oracle']['passed'] else 'FAIL'}  "
                  f"{'agree' if d['agree'] else 'DISAGREE' if d['agree'] is False else '-'}  image {str(d['vlm']['image_sha256'])[:12]}")
        else:
            print(f"  segment {v['segment']} {v['event']} {'D' if v['decides'] else '-'}  oracle {'PASS' if v['passed'] else 'FAIL'}")
    calls = caller.log
    vlm_calls = [c for c in calls if c["kind"] == "vlm"]
    check("the log has the planning and the labeling call, then one VLM call per deciding check, each with its prompt and reply (and image)",
          [c["kind"] for c in calls[:2]] == ["plan", "label"] and len(vlm_calls) == (len(deciding) if args.checker == "vlm" else 0) and len(calls) == 2 + len(vlm_calls)
          and all(c["prompt"] and c["reply_text"] for c in calls) and all(json.loads(c["reply_text"]) for c in calls[:2]) and all(c.get("image_sha256") for c in vlm_calls)
          and all(c["from_cache"] == (caller.mode == "cache_only") for c in calls if caller.mode != "cache_or_live"), f"{[(c['kind'], c['from_cache'], c['attempts'], c['seconds']) for c in calls]}")
    if args.checker == "vlm":
        check("every deciding check has a VLM verdict and the oracle's verdict beside it, and the decision is the VLM's",
              len(deciding) == 2 and all(v["details"]["vlm"]["verdict"] in ("YES", "NO") and "passed" in v["details"]["oracle"] and v["passed"] == (v["details"]["vlm"]["verdict"] == "YES") for v in deciding),
              f"{[(v['details']['vlm']['verdict'], v['details']['oracle']['passed'], v['details']['agree']) for v in deciding]}")
        check("each deciding check took its image on its own tick by rendering it on demand, and the oracle's verdict is from the same call",
              all(v["details"]["frozen"]["image_source"] == "render" and v["details"]["frozen"]["tick"] is not None for v in deciding), f"{[v['details']['frozen'] for v in deciding]}")
    print(f"\nthe drop monitor (logs only): {state['monitors'] if state['monitors'] else 'nothing logged'}")
    print(f"the skill ends (logged beside, not part of any check): {state['skill_end']}")
    check("the drop monitor logged no drop and no error in this clean run (a measurement: a drop here would be reported, not hidden)", state["monitors"] == [], f"{state['monitors']}")
    check("the place's return to home is its own log line after the skill ended, with the arm at home", len(state["skill_end"]) == 1 and state["skill_end"][0]["at_home"], f"{state['skill_end']}")
    finish("done")
    blob = (out / "llm_log.json").read_text() + (out / "summary.json").read_text()
    from src.llm_gemini import load_api_key
    try:
        key = load_api_key()
    except LLMError:
        key = None
    check("the key is in neither the log nor the summary", key is None or key not in blob)
    del sim, task, pipe
    gc.collect()
    r = replay_run(out / "recording", video="none", quiet=True)
    check("the replay is bit-identical", r["ok"], f"{r['ticks']} ticks, mismatch {r['mismatch']}")
    if not args.out:
        shutil.rmtree(out, ignore_errors=True)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--live", action="store_true", help="call the API (bypass the cache for reading, store the replies); same as --mode live")
    ap.add_argument("--mode", choices=("cache_only", "cache_or_live", "live"), help="the LLM mode; cache_or_live reads the stored reply of each call and calls the API only for the missing ones")
    ap.add_argument("--instruction", default="put the beaker on the hotplate")
    ap.add_argument("--no-stop-on-disagreement", action="store_true")
    ap.add_argument("--checker", choices=("oracle", "vlm"), default="vlm", help="who decides the completion checks: the VLM (the paper; default) or the sim oracle")
    ap.add_argument("--out", help="keep the log, the summary, the episode and the recording here")
    a = ap.parse_args()
    main(a)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if results and all(results) else 1)
